import pandas as pd,numpy as np
from itertools import product
from sklearn.linear_model import LogisticRegression
from sklearn.ensemble import RandomForestClassifier
from sklearn.model_selection import cross_val_score
tr=pd.read_csv('train.csv');te=pd.read_csv('test.csv')
print(tr.label.value_counts().to_dict(),te.label.value_counts().to_dict())
print('exact dup train/test',len(set(tr.sequence)&set(te.sequence)),'dup in train',tr.sequence.duplicated().sum())
print(tr.sequence.str.len().describe()[['min','max']].tolist())
def gc(s):return (s.count('G')+s.count('C'))/len(s)
for d in (tr,te):d['gc']=d.sequence.map(gc)
print(tr.groupby('label').gc.describe(),te.groupby('label').gc.describe())
# shared 30-mers
def km(s,k=30):return {s[i:i+k] for i in range(len(s)-k+1)}
trk=set().union(*map(km,tr.sequence))
