K=4;ks=[''.join(p) for p in product('ACGT',repeat=K)];ix={k:i for i,k in enumerate(ks)}
def f(s):
    v=np.zeros(len(ks))
    for i in range(len(s)-K+1):
        j=ix.get(s[i:i+K]);
        if j is not None:v[j]+=1
    return v/v.sum()
X=np.array([f(s) for s in tr.sequence]);Xt=np.array([f(s) for s in te.sequence])
y=tr.label.values;yt=te.label.values
